code.java:
class Solution {
    public int xorBeauty(int[] nums){
        int answer=0;
        for(int value:nums)answer^=value;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun xorBeauty(nums:IntArray):Int=nums.fold(0){
        answer,value->answer xor value
    }
}

code.cpp:
class Solution {
    public:int xorBeauty(vector<int>& nums){
        return accumulate(nums.begin(),nums.end(),0,bit_xor<int>());
    }
};
